#!/usr/bin/env bash
# rebalance-shards.sh — Regenerate .github/bats-shard-assignments.tsv from
# profiling data or test counts.  Uses greedy bin-packing (largest-first,
# assign to lightest shard) to minimise the maximum shard weight.
#
# Usage:
#   rebalance-shards.sh [--shards N] [--timing FILE] [--dry-run]
#
# --timing FILE   Use wall-clock seconds from a profiling TSV as weights
#                 (produced by profile-bats-timing.sh).  Without it, uses
#                 the per-file @test count as the weight.
# --shards N      Number of shards (default: 4).
# --dry-run       Print the assignment without writing it.

set -euo pipefail

REPO_ROOT="$(cd "$(dirname "$0")/../.." && pwd)"
N_SHARDS=4
TIMING_FILE=""
DRY_RUN=0

while [ $# -gt 0 ]; do
  case "$1" in
    --shards)   N_SHARDS="$2"; shift 2 ;;
    --timing)   TIMING_FILE="$2"; shift 2 ;;
    --dry-run)  DRY_RUN=1; shift ;;
    *)          echo "Unknown arg: $1" >&2; exit 1 ;;
  esac
done

TESTS_DIR="$REPO_ROOT/plugins/gaia/tests"
OUT="$REPO_ROOT/.github/bats-shard-assignments.tsv"

python3 -I - "$TESTS_DIR" "$N_SHARDS" "$TIMING_FILE" "$OUT" "$DRY_RUN" << 'PYEOF'
import os, sys

tests_dir = sys.argv[1]
n_shards  = int(sys.argv[2])
timing_f  = sys.argv[3]
out_path  = sys.argv[4]
dry_run   = sys.argv[5] == "1"

# Collect weights.
weights = {}
if timing_f:
    with open(timing_f) as fh:
        for line in fh:
            if line.startswith("file") or line.startswith("#"):
                continue
            parts = line.strip().split("\t")
            if len(parts) >= 3:
                weights[parts[0]] = max(int(parts[2]), 1)

# Fall back to test counts for files not in timing data.
for f in sorted(os.listdir(tests_dir)):
    if f.endswith(".bats") and os.path.isfile(os.path.join(tests_dir, f)):
        if f not in weights:
            count = 0
            with open(os.path.join(tests_dir, f)) as fh:
                for line in fh:
                    if line.startswith("@test "):
                        count += 1
            weights[f] = max(count, 1)

# Greedy bin-packing.
shards = {i: [] for i in range(1, n_shards + 1)}
shard_w = {i: 0 for i in range(1, n_shards + 1)}

for f, w in sorted(weights.items(), key=lambda x: -x[1]):
    lightest = min(shard_w, key=shard_w.get)
    shards[lightest].append((f, w))
    shard_w[lightest] += w

# Summary.
total = sum(shard_w.values())
avg = total / n_shards
max_w = max(shard_w.values())
for s in range(1, n_shards + 1):
    print(f"Shard {s}: {len(shards[s])} files, weight {shard_w[s]}")
print(f"Total: {sum(len(v) for v in shards.values())} files, weight {total}")
print(f"Average: {avg:.0f}, Max: {max_w}, Ratio: {max_w/avg:.2f}")

if dry_run:
    print("\n(dry run — not writing)")
    sys.exit(0)

# Write TSV.
with open(out_path, "w") as out:
    out.write("# Shard assignment for top-level bats files under plugins/gaia/tests/.\n")
    out.write("# Generated by rebalance-shards.sh using greedy bin-packing.\n")
    out.write("# Each file is assigned to exactly one shard. Rebalance with:\n")
    out.write("#   .github/scripts/rebalance-shards.sh [--timing profiling/bats-timing.tsv]\n")
    out.write("#\n")
    out.write("# shard\tfile\ttests\n")
    for s in range(1, n_shards + 1):
        for f, w in sorted(shards[s]):
            out.write(f"{s}\t{f}\t{w}\n")

print(f"\nWrote {out_path}")
PYEOF
